-- NWP lessons 15-19. Idempotent; all lessons remain unpublished drafts.
with c as (select id from public.academy_courses where id='meteorology-forecasting-foundations'),
ch as (
 insert into public.academy_chapters(course_id,title,description,sort_order,published)
 select id,'النمذجة العددية الجوية والتنبؤ التشغيلي','مبادئ النماذج العددية وشبكاتها وشروطها واستيعاب البيانات وقراءة المخرجات.',5,false
 from c on conflict(course_id,title) do update set description=excluded.description returning id,course_id
),
u1 as (
 insert into public.academy_units(chapter_id,title,description,sort_order,published)
 select id,'مدخل إلى النمذجة العددية','مفهوم التنبؤ العددي وبنية الشبكات ودقتها.',1,false from ch
 on conflict(chapter_id,title) do update set description=excluded.description returning id,chapter_id
),
u2 as (
 insert into public.academy_units(chapter_id,title,description,sort_order,published)
 select id,'بنية النماذج ودقتها','الشبكات العددية والدقة الأفقية والرأسية والزمنية.',2,false from ch
 on conflict(chapter_id,title) do update set description=excluded.description returning id,chapter_id
),
u3 as (
 insert into public.academy_units(chapter_id,title,description,sort_order,published)
 select id,'تهيئة النماذج واستيعاب البيانات','الشروط الابتدائية والحدودية ودمج الرصد.',3,false from ch
 on conflict(chapter_id,title) do update set description=excluded.description returning id,chapter_id
),
u4 as (
 insert into public.academy_units(chapter_id,title,description,sort_order,published)
 select id,'تفسير المخرجات العددية','قراءة حقول النماذج والتحقق من التوقعات.',4,false from ch
 on conflict(chapter_id,title) do update set description=excluded.description returning id,chapter_id
),
d(slug,title,summary,content,ord,mins,objectives,unit) as (values
('numerical-weather-prediction-introduction','مقدمة في التنبؤ العددي بالطقس','مبادئ تحويل الغلاف الجوي إلى نظام معادلات وحساب تطوره باستخدام الحواسيب.','{"blocks":[{"type":"heading","text":"ما التنبؤ العددي؟"},{"type":"text","text":"التنبؤ العددي بالطقس (NWP) هو استخدام معادلات فيزيائية ورياضية تصف حركة الغلاف الجوي وتبادل الطاقة والرطوبة، ثم حلها عددياً على الحاسوب لتقدير تطور الحالة الجوية مستقبلاً."},{"type":"heading","text":"سلسلة العمل الأساسية"},{"type":"list","items":["جمع الرصد من المحطات والرادارات والأقمار الصناعية والطائرات والبالونات.","فحص البيانات وضبط جودتها ثم دمجها في تحليل ابتدائي ثلاثي الأبعاد.","تهيئة الشروط الابتدائية والحدودية وتشغيل النموذج.","إنتاج حقول التنبؤ ومخرجات التشخيص.","التحقق من التوقعات ومقارنتها بالرصد وإصدار التفسير التشغيلي."]},{"type":"heading","text":"ما الذي يحسبه النموذج؟"},{"type":"text","text":"تحسب النماذج متغيرات مثل الرياح ودرجة الحرارة والضغط والرطوبة، وتستخدم معادلات الحركة والطاقة والاستمرارية وحفظ الماء، إلى جانب تمثيل عمليات أصغر من شبكة النموذج."},{"type":"heading","text":"النموذج ليس صورة للمستقبل"},{"type":"text","text":"الناتج العددي تقدير مشروط بالشروط الابتدائية والحدودية وبالتمثيلات الفيزيائية ودقة الشبكة. لذلك قد تختلف النماذج أو تتغير توقعاتها بين دورة وأخرى."},{"type":"heading","text":"أنواع النماذج"},{"type":"list","items":["نماذج عالمية تغطي الكرة الأرضية وتصف الأنظمة واسعة النطاق.","نماذج إقليمية محدودة المجال بدقة أعلى نسبياً وتحتاج إلى حدود جانبية.","نماذج حتمية تنتج مساراً واحداً، ونماذج مجموعات تنتج عدة أعضاء لتقدير عدم اليقين."]},{"type":"heading","text":"مفاهيم يجب التمييز بينها"},{"type":"list","items":["الرصد: قياس فعلي أو تقدير من جهاز.","التحليل: أفضل تمثيل لحالة الجو عند وقت مرجعي بعد دمج مصادر البيانات.","التنبؤ: تطور متوقع انطلاقاً من التحليل.","التحقق: مقارنة التنبؤ بما تحقق فعلياً باستخدام مقاييس مناسبة."]},{"type":"callout","text":"لا تتعامل مع قيمة نموذجية منفردة على أنها حقيقة مؤكدة. راجع الرصد، وتعدد النماذج، واتساق التوقعات، ومقدار عدم اليقين."},{"type":"example","title":"مثال تطبيقي","text":"مثال: يتوقع نموذج هطولاً بعد 36 ساعة. افحص موقع الحزام المطري وتوقيته وشدته في أكثر من تشغيل، ثم قارنه بالرطوبة والحركة الرأسية والرصد المتاح قبل صياغة التوقع."},{"type":"heading","text":"خلاصة الدرس"},{"type":"text","text":"التنبؤ العددي منظومة تبدأ بالرصد والتحليل وتنتهي بالتوقع والتحقق. جودة النتيجة تعتمد على البيانات والفيزياء والدقة والتفسير البشري."}]}',150,35,'["شرح مفهوم التنبؤ العددي ومراحله الأساسية","تمييز النموذج عن الرصد والتحليل","تحديد أهم مصادر عدم اليقين"]','مدخل إلى النمذجة العددية'),
('nwp-grid-horizontal-vertical-resolution','الشبكات العددية والدقة الأفقية والرأسية','افهم شبكة النموذج وتمثيل المجال الجوي وتأثير الدقة على التضاريس والظواهر الجوية.','{"blocks":[{"type":"heading","text":"ما الشبكة العددية؟"},{"type":"text","text":"يقسم النموذج المجال الجوي إلى نقاط أو خلايا حسابية أفقياً ورأسياً. تُخزن المتغيرات أو تحسب على مواقع محددة ضمن الشبكة، ثم تتقدم المعادلات خطوة زمنية بعد أخرى."},{"type":"heading","text":"الدقة الأفقية"},{"type":"text","text":"تعبر عن المسافة المميزة بين نقاط الشبكة أو حجم الخلية أفقياً. تقليل المسافة يعني عادة دقة مكانية أعلى، لكنه يزيد كلفة الحساب والبيانات المطلوبة."},{"type":"heading","text":"الدقة الرأسية"},{"type":"text","text":"تصف عدد المستويات وكيفية توزيعها من قرب السطح حتى أعلى الغلاف الجوي. يؤثر توزيع المستويات في تمثيل الطبقة الحدية والسحب والطبقات المستقرة والتروبوبوز."},{"type":"heading","text":"الدقة الزمنية"},{"type":"text","text":"تشير إلى الفاصل الزمني بين مخرجات النموذج، بينما الخطوة الزمنية الحسابية الداخلية قد تكون أقصر بكثير. لا تخلط بين تكرار نشر الخرائط والخطوة الحسابية."},{"type":"heading","text":"ما الذي لا تحله زيادة الدقة وحدها؟"},{"type":"text","text":"بعض العمليات أصغر من خلية الشبكة، مثل الاضطراب الدقيق والعديد من السحب الحملية. تحتاج هذه العمليات إلى تمثيلات فيزيائية أو إلى نماذج تسمح بحلها جزئياً عند دقة مناسبة."},{"type":"heading","text":"تأثير التضاريس والسواحل"},{"type":"text","text":"قد تمثل الشبكة الجبال والوديان وخطوط الساحل بصورة مبسطة. لذلك قد تختلف الرياح والهطولات المحلية عن الواقع، خاصة عندما تكون التضاريس معقدة أو أصغر من مقياس الشبكة."},{"type":"list","items":["الدقة الأعلى قد تحسن تمثيل بعض التفاصيل لكنها لا تضمن توقعاً أدق في كل حالة.","قارن الدقة مع نوع الظاهرة وحجمها ومهلة التنبؤ.","تحقق من وصف النموذج وإصداره وشبكته قبل مقارنة المنتجات."]},{"type":"callout","text":"لا تقارن نموذجين اعتماداً على رقم الدقة الأفقية وحده؛ فالفيزياء واستيعاب البيانات والشروط الحدودية وجودة الرصد عوامل مؤثرة أيضاً."},{"type":"example","title":"مثال تطبيقي","text":"مثال: نموذج إقليمي شبكته أدق من نموذج عالمي في منطقة جبلية. قد يصف فروق الارتفاعات بصورة أفضل، لكن ذلك لا يضمن تلقائياً توقيت الهطول أو شدته دون تحقق."},{"type":"heading","text":"خلاصة الدرس"},{"type":"text","text":"الشبكة تحدد كيف يمثل النموذج المكان والارتفاع والزمن. فهم الدقة ضروري لتفسير حدود الخرائط وعدم المبالغة في التفاصيل المحلية."}]}',160,35,'["شرح مفهوم الشبكة العددية وخلاياها","التمييز بين الدقة الأفقية والرأسية والزمنية","تفسير أثر الدقة على الظواهر والتمثيل الفيزيائي"]','بنية النماذج ودقتها'),
('initial-and-boundary-conditions-nwp','الشروط الابتدائية والحدودية في النماذج العددية','تعرف إلى حالة البداية للنموذج والحدود الجانبية والسطحية وتأثيرها على التنبؤ.','{"blocks":[{"type":"heading","text":"الشروط الابتدائية"},{"type":"text","text":"الشروط الابتدائية هي التوزيع ثلاثي الأبعاد للمتغيرات الجوية عند وقت بدء التكامل العددي، مثل الرياح والحرارة والرطوبة والضغط. تمثل هذه الحالة التحليلية نقطة انطلاق النموذج."},{"type":"heading","text":"لماذا يصعب تحديد حالة البداية بدقة؟"},{"type":"text","text":"الرصد غير متجانس مكانياً وزمنياً، وبعض المناطق والمستويات أقل تغطية. كما تحمل القياسات أخطاء وأوجه عدم يقين، وقد لا تتوافق مصادر الرصد تماماً قبل ضبطها ودمجها."},{"type":"heading","text":"الشروط الحدودية"},{"type":"text","text":"تحدد سلوك المجال عند حدوده. في النموذج الإقليمي المحدود المجال، توفر النماذج العالمية عادة معلومات متغيرة زمنياً عند الحدود الجانبية، بينما تمثل الحدود السطحية خصائص الأرض والبحر والتضاريس والتدفقات."},{"type":"heading","text":"مصادر الخطأ"},{"type":"list","items":["أخطاء القياس أو تمثيل الرصد.","نقص التغطية المكانية أو الرأسية.","عدم تمثيل بعض العمليات الفيزيائية بصورة كافية.","أخطاء الحدود الجانبية أو اختلاف النموذج المغذي.","حساسية تطور الغلاف الجوي للاختلافات الصغيرة في البداية."]},{"type":"heading","text":"التهيئة والتوازن"},{"type":"text","text":"تستخدم إجراءات التهيئة لتقليل التناقضات غير المرغوبة بين المتغيرات أو بين الرصد والنموذج. تختلف طرق التهيئة بحسب نظام النموذج وطريقة استيعاب البيانات."},{"type":"heading","text":"أثر ذلك على التوقع"},{"type":"text","text":"قد تتضخم بعض الاختلافات مع الزمن، ولذلك تكون الثقة عادة مرتبطة بمهلة التنبؤ ونوع الحالة الجوية واتساق أعضاء المجموعة والنماذج."},{"type":"callout","text":"لا تعني الشروط الابتدائية الجيدة أن التنبؤ مضمون؛ فالفيزياء والحدود والتطور الفوضوي للغلاف الجوي تظل مصادر لعدم اليقين."},{"type":"example","title":"مثال تطبيقي","text":"مثال: يتغير موضع منخفض متوقع بين تشغيلين متتاليين. افحص اختلاف التحليل الابتدائي والرصد المستوعب، ثم راقب ما إذا كان التغير مستمراً في تشغيلات لاحقة أو جزءاً من تذبذب طبيعي."},{"type":"heading","text":"خلاصة الدرس"},{"type":"text","text":"الشروط الابتدائية تصف حالة البداية، والحدودية تصف ما يدخل أو يحدث عند حدود المجال. كلاهما أساس لفهم جودة التنبؤ العددي."}]}',170,35,'["تعريف الشروط الابتدائية والحدودية","شرح أثر أخطاء الحالة الابتدائية على التوقع","تمييز الحدود الجانبية والسطحية في النماذج الإقليمية"]','بنية النماذج ودقتها'),
('meteorological-data-assimilation','استيعاب البيانات الجوية (Data Assimilation)','تعرف إلى دمج الرصد مع خلفية النموذج لإنتاج تحليل جوي متوازن.','{"blocks":[{"type":"heading","text":"ما استيعاب البيانات؟"},{"type":"text","text":"استيعاب البيانات هو إطار رياضي لدمج المشاهدات الجوية مع توقع خلفي قصير الأمد من النموذج لإنتاج تحليل يمثل الحالة الجوية بأفضل تقدير ممكن وفق المعلومات المتاحة وأخطاء مصادرها."},{"type":"heading","text":"الخلفية والرصد والتحليل"},{"type":"list","items":["الخلفية (Background): توقع قصير الأمد يوفر تخميناً مكانياً ورأسياً متكاملاً.","الرصد (Observation): قياسات المحطات والبالونات والطائرات والرادار والأقمار وغيرها.","التحليل (Analysis): الحالة الناتجة من الموازنة بين الخلفية والرصد وفق تقديرات الأخطاء."]},{"type":"heading","text":"لماذا لا ننسخ الرصد مباشرة؟"},{"type":"text","text":"الرصد غير متساوٍ في الدقة والتوزيع والتوقيت، وبعض القياسات تمثل حجماً أو طبقة مختلفة عن نقطة الشبكة. لذلك يجب فحص الجودة وتحويل القياس إلى ما يمكن مقارنته بالنموذج."},{"type":"heading","text":"مراقبة جودة البيانات"},{"type":"list","items":["فحوص المدى والقيم غير المنطقية.","مقارنة الرصد بالخلفية واكتشاف الانحرافات الكبيرة.","التحقق من الموقع والارتفاع والتوقيت والوحدة.","استبعاد أو تخفيض وزن القياسات غير الموثوقة وفق نظام ضبط الجودة."]},{"type":"heading","text":"مقاربات شائعة"},{"type":"text","text":"تستخدم أنظمة متنوعة مثل الاستيعاب التغايري ثلاثي الأبعاد (3D-Var)، والاستيعاب رباعي الأبعاد (4D-Var) الذي يستفيد من التطور الزمني خلال نافذة الاستيعاب، وطرائق المرشحات التجميعية مثل EnKF. تختلف التفاصيل والتطبيقات بين مراكز التنبؤ."},{"type":"heading","text":"أخطاء الرصد والخلفية"},{"type":"text","text":"تحدد مصفوفات أو نماذج الأخطاء مقدار الثقة النسبية في الرصد والخلفية. إذا كان الرصد موثوقاً وممثلاً جيداً فقد يؤثر بقوة في التحليل، أما الرصد المشكوك فيه فلا ينبغي أن يفرض تغيراً غير واقعي."},{"type":"heading","text":"من التحليل إلى التنبؤ"},{"type":"text","text":"يستخدم التحليل كحالة ابتدائية للنموذج، ثم يبدأ التكامل العددي. لذلك تؤثر جودة استيعاب البيانات في تمثيل المنخفضات والجبهات والرطوبة والرياح والأنظمة الصغيرة."},{"type":"callout","text":"استيعاب البيانات ليس مجرد إدخال كل القياسات إلى النموذج؛ إنه دمج مضبوط إحصائياً وفيزيائياً مع مراقبة جودة وتمثيل أخطاء."},{"type":"example","title":"مثال تطبيقي","text":"مثال: يصل رصد بالون جوي بحرارة تختلف كثيراً عن الخلفية. يفحص النظام جودة الجهاز والموقع والتوقيت والطبقة، ثم يقرر وزن الرصد أو استبعاده قبل بناء التحليل."},{"type":"heading","text":"خلاصة الدرس"},{"type":"text","text":"يحوّل استيعاب البيانات الرصد المتفرق والخلفية النموذجية إلى تحليل متوازن. جودته تعتمد على الرصد وضبط الجودة وتمثيل الأخطاء وطريقة الدمج."}]}',180,40,'["تعريف استيعاب البيانات الجوية","شرح دور الخلفية والرصد وأخطاء كل منهما","تمييز مفاهيم 3D-Var و4D-Var والمرشح التجميعي بصورة تمهيدية"]','تهيئة النماذج واستيعاب البيانات'),
('interpreting-nwp-model-output','مخرجات النماذج العددية وكيفية تفسيرها','تعلم قراءة خرائط النماذج والحقول الأساسية والمقارنة بين التشغيلات والتحقق من الإشارات.','{"blocks":[{"type":"heading","text":"ما مخرجات النموذج؟"},{"type":"text","text":"المخرجات حقول عددية تمثل متغيرات جوية عند أوقات ومستويات محددة. تعرض عادة على خرائط أفقية أو مقاطع رأسية أو سلاسل زمنية أو جداول لنقاط محددة."},{"type":"heading","text":"اقرأ بيانات المنتج أولاً"},{"type":"list","items":["اسم النموذج وإصداره ومصدر البيانات.","وقت بدء التشغيل (Run initialization).","مهلة التنبؤ (Forecast lead time) والوقت الصالح للخريطة.","المستوى الرأسي أو نوع السطح.","الوحدة وطريقة حساب المتغير، وهل هو لحظي أم تراكمي."]},{"type":"heading","text":"حقول أساسية"},{"type":"list","items":["الضغط عند مستوى سطح البحر: لتحديد مراكز الضغط والجبهات بصورة مساعدة.","الارتفاع الجهدي عند 500 hPa: لتحليل الأخاديد والنتوءات والموجات.","الرياح عند 850 و700 و500 و300 hPa: لفهم النقل والقص والتيار النفاث.","الحرارة والرطوبة: لتقييم الكتل الهوائية والتشبع والاستقرار.","الحركة الرأسية: لتشخيص مناطق الصعود والهبوط مع التحقق من اصطلاح الإشارة.","الهطول: افهم هل المنتج تراكمي خلال فترة أم معدل أم قيمة لفترة زمنية."]},{"type":"heading","text":"الفرق بين اللحظي والتراكمي"},{"type":"text","text":"درجة الحرارة والرياح غالباً حقول صالحة لوقت محدد، بينما الهطول قد يعرض مجموعاً تراكمياً منذ بداية التشغيل أو خلال فترة بين مخرجين. يجب قراءة تعريف المنتج قبل طرح قيم أو مقارنتها."},{"type":"heading","text":"المقارنة بين النماذج"},{"type":"list","items":["وحّد الوقت الصالح ومهلة التنبؤ والمنطقة والمستوى قبل المقارنة.","قارن موقع النظام وتوقيته وبنيته، لا قيمة بكسل واحدة فقط.","افحص اتساق التشغيلات المتتابعة ومجموعة التوقعات.","ميّز بين اختلاف حقيقي في السيناريو واختلاف ناتج عن الدقة أو المعالجة."]},{"type":"heading","text":"تحويل الخرائط إلى توقع تشغيلي"},{"type":"text","text":"ابدأ بالنمط واسع النطاق، ثم حدد الأنظمة المؤثرة، ثم افحص الرطوبة والاستقرار والحركة الرأسية والرياح والحرارة. قارن ذلك بالرصد المحلي والتضاريس والتحذيرات المعتمدة، وصغ التوقع مع تحديد المكان والفترة ودرجة الثقة."},{"type":"callout","text":"لا تقرأ خريطة الهطول دون معرفة نافذتها الزمنية، ولا تقارن خرائط من تشغيلات أو مستويات مختلفة كما لو كانت متطابقة."},{"type":"example","title":"مثال تطبيقي","text":"مثال: يعرض منتج هطولاً تراكمياً من 00 إلى 12 UTC، بينما يعرض منتج آخر مجموع 6 ساعات. لا تقارن الرقمين مباشرة؛ وحّد الفترة الزمنية أولاً، ثم افحص توزيع الهطول وتوافقه مع الرصد."},{"type":"heading","text":"قائمة فحص قبل اعتماد التوقع"},{"type":"list","items":["هل وقت التشغيل والوقت الصالح صحيحان؟","هل الوحدة والمستوى ونوع الحقل معروف؟","هل تمت مقارنة أكثر من نموذج أو عضو عند الحاجة؟","هل تتفق الإشارات مع الرصد والتحليل السينوبتيكي؟","هل حُددت درجة الثقة ومصادر عدم اليقين؟"]},{"type":"heading","text":"خلاصة الدرس"},{"type":"text","text":"قراءة مخرجات النماذج مهارة تفسيرية وليست نسخاً للأرقام. يلزم فهم الحقل ووحدته وتوقيته ومقارنته بالرصد والسياق الديناميكي."}]}',190,45,'["قراءة حقول الحرارة والضغط والرياح والرطوبة والهطول","التمييز بين التوقع التراكمي واللحظي","بناء مقارنة منهجية بين النماذج والتشغيلات"]','تفسير المخرجات العددية')
)
insert into public.academy_lessons
(course_id,chapter_id,unit_id,slug,title,summary,content,published,sort_order,level,estimated_minutes,learning_objectives,chapter_title,unit_title)
select c.id,ch.id,
case d.unit when 'مدخل إلى النمذجة العددية' then u1.id when 'بنية النماذج ودقتها' then u2.id when 'تهيئة النماذج واستيعاب البيانات' then u3.id else u4.id end,
d.slug,d.title,d.summary,d.content::jsonb,false,d.ord,'intermediate',d.mins,d.objectives::jsonb,
'النمذجة العددية الجوية والتنبؤ التشغيلي',d.unit
from d cross join c cross join ch cross join u1 cross join u2 cross join u3 cross join u4
on conflict(course_id,slug) do update set
chapter_id=excluded.chapter_id,unit_id=excluded.unit_id,title=excluded.title,summary=excluded.summary,
content=excluded.content,published=false,sort_order=excluded.sort_order,level=excluded.level,
estimated_minutes=excluded.estimated_minutes,learning_objectives=excluded.learning_objectives,
chapter_title=excluded.chapter_title,unit_title=excluded.unit_title;